#!/usr/bin/env node
'use strict';
// Writes the phone's bundled screen profiles from the provider registry.
// Run: node scripts/generate-agent-profiles.cjs. --check reports drift without writing.
const fs = require('node:fs');
const path = require('node:path');
const { screenProfiles, consoleFeatures } = require('../electron/providers/index.cjs');
const target = path.join(__dirname, '..', 'mobile', 'lib', 'agent_profile_data.dart');

function render(profiles = screenProfiles) {
  return `// Generated by scripts/generate-agent-profiles.cjs from electron/providers.
// Do not edit. Used when the PC serves no usable profile.
const agentProfilesJson = r'''
${JSON.stringify(profiles, null, 2)}
''';
const consoleFeaturesJson = r'''
${JSON.stringify(consoleFeatures, null, 2)}
''';
`;
}

if (require.main === module) {
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') : '';
    if (current !== render()) { console.error('mobile/lib/agent_profile_data.dart is out of date. Run node scripts/generate-agent-profiles.cjs.'); process.exitCode = 1; }
    else console.log('PASS agent profile data');
  } else fs.writeFileSync(target, render());
}

module.exports = { render, target };
